 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    fixed = {(r, c) for r in range(h) for c in range(w) if grid[r][c] == 2}
    # The full row of 2s marks the wall; objects settle toward it.
    wall_rows = [r for r in range(h) if all(grid[r][c] == 2 for c in range(w))]
    upward = bool(wall_rows and wall_rows[0] == 0)

    seen = set(fixed)
    pieces = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or color == 2 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                rr, cc = stack.pop()
                cells.append((rr, cc))
                for nr, nc in ((rr-1, cc), (rr+1, cc), (rr, cc-1), (rr, cc+1)):
                    if (0 <= nr < h and 0 <= nc < w and (nr, nc) not in seen
                            and grid[nr][nc] == color):
                        seen.add((nr, nc))
                        stack.append((nr, nc))
            pieces.append((color, cells))

    # Process objects nearest the wall first, then let each translate rigidly
    # until it touches the wall or an already/static object.
    if upward:
        pieces.sort(key=lambda p: min(r for r, _ in p[1]))
        dr = -1
    else:
        pieces.sort(key=lambda p: -max(r for r, _ in p[1]))
        dr = 1

    occupied = set(fixed)
    settled = []
    for color, cells in pieces:
        current = set(cells)
        while True:
            moved = {(r + dr, c) for r, c in current}
            if any(r < 0 or r >= h or c < 0 or c >= w for r, c in moved):
                break
            if moved & occupied:
                break
            current = moved
        occupied |= current
        settled.append((color, current))

    out = [[0] * w for _ in range(h)]
    for r, c in fixed:
        out[r][c] = 2
    for color, cells in settled:
        for r, c in cells:
            out[r][c] = color
    return out
